// Generated by apps/tools/scripts/format-names.mjs from content/formats.json;
// don't edit. The formats whose name isn't their key in upper case.
export const FORMAT_NAMES: Readonly<Record<string, string>> = {
  actionscript: "ActionScript",
  asciidoc: "AsciiDoc",
  avro: "Avro",
  bbcode: "BBCode",
  divx: "DivX",
  firebase: "Firebase",
  image: "Image",
  jira: "Jira",
  jp2: "JPEG 2000",
  jsonlines: "JSON Lines",
  jxl: "JPEG XL",
  latex: "LaTeX",
  markdown: "Markdown",
  mediawiki: "MediaWiki",
  mpeg2: "MPEG-2",
  mysql: "MySQL",
  opus: "Opus",
  pandasdataframe: "Pandas DataFrame",
  protobuf: "Protobuf",
  qlik: "Qlik",
  rdataframe: "R data frame",
  restructuredtext: "reStructuredText",
  ruby: "Ruby",
  textile: "Textile",
  tracwiki: "Trac Wiki",
  webm: "WebM",
  webp: "WebP",
};

// A format as people write it: "WebP", "WebM", "MP4".
export function formatName(format: string): string {
  return FORMAT_NAMES[format] ?? format.toUpperCase();
}
